<?php
declare(strict_types=1);
$root=dirname(__DIR__);require_once $root.'/config/config.php';require_once $root.'/includes/services/MessagingService.php';
$pdo=db();$players=$pdo->query('SELECT id FROM players ORDER BY id LIMIT 2')->fetchAll(PDO::FETCH_COLUMN);if(count($players)<2){fwrite(STDERR,"message_participants_missing\n");exit(2);} $sender=(int)$players[0];$recipient=(int)$players[1];$subject='Contract Test '.substr(str_replace('.','',uniqid('',true)),-8);$service=new MessagingService($pdo);$pdo->prepare("DELETE FROM blacklists WHERE (player_id=? AND blocked_player_id=?) OR (player_id=? AND blocked_player_id=?)")->execute([$sender,$recipient,$recipient,$sender]);$pdo->prepare("DELETE FROM player_cooldowns WHERE player_id=? AND cooldown_key='message_send'")->execute([$sender]);$messageId=$service->send($sender,$recipient,$subject,'Message contract body');$q=$pdo->prepare('SELECT sender_id,recipient_id,subject,read_at FROM messages WHERE id=?');$q->execute([$messageId]);$message=$q->fetch(PDO::FETCH_ASSOC);$n=$pdo->prepare("SELECT COUNT(*) FROM player_notifications WHERE player_id=? AND notification_type='message' AND title='New message from commander' AND body=?");$n->execute([$recipient,$subject]);$checks=['message_created'=>is_array($message)&&(int)$message['sender_id']===$sender&&(int)$message['recipient_id']===$recipient,'notification_created'=>(int)$n->fetchColumn()===1];$read=$service->markRead($recipient,$messageId);$q->execute([$messageId]);$readRow=$q->fetch(PDO::FETCH_ASSOC);$checks['recipient_read']=($read['state']??'')==='success'&&$readRow['read_at']!==null;$service->blacklist($recipient,$sender,'contract test block');$checks['blacklist_created']=(int)$pdo->query("SELECT COUNT(*) FROM blacklists WHERE player_id=".$recipient." AND blocked_player_id=".$sender)->fetchColumn()===1;$blocked=false;try{$service->send($sender,$recipient,$subject.' blocked','Should fail');}catch(Throwable $e){$blocked=str_contains(strtolower($e->getMessage()),'blocked');}$checks['blacklist_enforced']=$blocked;$inbox=$service->inbox($recipient);$checks['inbox_ready']=in_array($inbox['state'],['ready','empty'],true);$pdo->prepare('DELETE FROM messages WHERE id=?')->execute([$messageId]);$pdo->prepare("DELETE FROM player_notifications WHERE player_id=? AND notification_type='message' AND title='New message from commander' AND body=?")->execute([$recipient,$subject]);$pdo->prepare('DELETE FROM blacklists WHERE player_id=? AND blocked_player_id=?')->execute([$recipient,$sender]);$pdo->prepare("DELETE FROM game_events WHERE entity_type='message' AND entity_id=?")->execute([$messageId]);$pdo->prepare("DELETE FROM game_events WHERE player_id=? AND event_type='player_blacklisted' AND entity_id=? AND created_at>=DATE_SUB(NOW(),INTERVAL 2 MINUTE)")->execute([$recipient,$sender]);$pdo->prepare("DELETE FROM player_cooldowns WHERE player_id=? AND cooldown_key='message_send'")->execute([$sender]);$failures=array_keys(array_filter($checks,static fn(bool $ok):bool=>!$ok));echo json_encode(['status'=>$failures?'failed':'passed','message_id'=>$messageId,'checks'=>$checks,'failures'=>$failures],JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR).PHP_EOL;exit($failures?1:0);
